// Case-insensitive lookup for the concierge/fact-checker: find a regulated
// activity by name fragment (e.g. "pharmacy", "real estate", "lawyer").
export function lookupRegulatedActivity(term: string): RegulatedActivity[] {
  const t = (term || '').trim().toLowerCase();
  if (t.length < 3) return [];
  return REGULATED_ACTIVITIES.filter((r) => r.sector.toLowerCase().includes(t));
}

